<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $quotation->quotation_number }}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:40px;font-size:13px}h1{font-size:24px;margin:0}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #bbb;padding:8px;text-align:left}th{background:#f2f2f2}.right{text-align:right}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:22px}.totals{margin-left:auto;width:320px;margin-top:18px}.terms{margin-top:35px}.sign{margin-top:70px}.actions{margin-bottom:20px}@media print{.actions{display:none}body{margin:15mm}}</style></head><body><div class="actions"><button onclick="window.print()">Print</button></div><h1>QUOTATION</h1><p><strong>{{ $quotation->quotation_number }}</strong></p><div class="meta"><div><strong>Customer:</strong><br>{{ $quotation->customer->company_name }}<br>{!! nl2br(e($quotation->customer->address)) !!}</div><div><strong>Date:</strong> {{ $quotation->quote_date?->format('d-M-Y') }}<br><strong>Valid Until:</strong> {{ $quotation->valid_until?->format('d-M-Y') ?? '—' }}<br><strong>Reference:</strong> {{ $quotation->reference ?: '—' }}<br><strong>Summary:</strong> {{ $quotation->summary ?: '—' }}</div></div><table><thead><tr><th>#</th><th>Description</th><th>Qty</th><th>Unit Price</th><th class="right">Amount</th></tr></thead><tbody>@foreach($quotation->items as $item)<tr><td>{{ $item->line_no }}</td><td>{{ $item->description }}</td><td>{{ rtrim(rtrim(number_format($item->quantity,4), '0'), '.') }} {{ $item->unit }}</td><td>{{ number_format($item->selling_price,2) }}</td><td class="right">{{ number_format(($item->selling_price*$item->quantity)-$item->discount+$item->tax_amount,2) }}</td></tr>@endforeach</tbody></table><div class="totals"><div>Subtotal: <span style="float:right">{{ number_format($quotation->subtotal,2) }}</span></div><div>Discount: <span style="float:right">{{ number_format($quotation->discount_total,2) }}</span></div><div>Tax: 